function editGroup(id=null){const g=groups.find(g=>g.id===id),d=panel(`<form id="groupForm"><div class="eyebrow">MORE VOICES, MORE STORIES</div><h2>${g?'编辑':'创建'}群聊</h2><label>群聊名字<input name="groupName" required maxlength="40" value="${escapeHtml(g?.name||'')}"></label><label>群聊氛围<textarea name="description" rows="3" maxlength="2000" placeholder="例如：朋友们的小茶会…">${escapeHtml(g?.prompt||'')}</textarea></label><div class="group-members">${roles.map(r=>`<label class="member-option">${avatarHTML('role:'+r.id,r.emoji)}<span>${escapeHtml(r.name)}</span><input type="checkbox" name="members" value="${r.id}" ${g?.members.includes(r.id)?'checked':''}></label>`).join('')}</div><p class="api-note">选择 2–6 位角色，同群后会互相认识。群内可安排自我介绍，角色参与过的聊天会成为共同经历，并带入后续私聊。每轮各角色分别调用一次 API。</p><div class="actions"><button class="secondary" type="button" id="cancelGroup">取消</button><button class="primary">保存群聊</button></div></form>`);$('#cancelGroup').onclick=()=>d.close();$('#groupForm').onsubmit=e=>{e.preventDefault();const f=e.target,members=[...f.querySelectorAll('[name="members"]:checked')].map(x=>x.value);if(members.length<2||members.length>6){toast('请选择 2–6 位角色');return}const group={...g,id:id||'group:'+crypto.randomUUID(),name:f.groupName.value.trim(),emoji:'♧',prompt:f.description.value.trim(),members};if(!group.name)return;groups=id?groups.map(x=>x.id===id?group:x):[...groups,group];relations=PalaisSocial.connect(relations,members,'group','在群聊「'+group.name+'」中认识');saveSocial();d.close();current=group.id;go('chat');toast('群聊已保存')}}
function renderChatList(){
  screen.innerHTML=`<section class="view">${wxHeading('微信','WECHAT · CONVERSATIONS','<button class="round" id="chatAdd" aria-label="创建角色或群聊">+</button>')}<div class="chat-links"><button id="openMoments">❀ 朋友圈</button><button id="openGroups">♧ 建群聊</button><button id="openMemories">♧ 记忆花园</button></div><div class="notice">${apiReady()?'✧ API 已连接，今天想聊些什么？':'先连接 API，再开启聊天。 <button id="chatApi">去设置 ↗</button>'}</div><div id="roleList"></div></section>`;
  bindWxHome();const list=$('#roleList');[...groups,...roles].forEach(r=>{const b=document.createElement('button');b.className='role';const last=(histories[r.id]||[]).at(-1);b.innerHTML=`${avatarHTML('role:'+r.id,r.emoji)}<div class="info"><strong>${escapeHtml(r.name)}${r.members?' <span class="mini-tag">群聊</span>':''}</strong><p>${escapeHtml(last?.content||'你的故事，等你开启。')}</p></div><span class="arrow">›</span>`;b.onclick=()=>{current=r.id;render()};list.append(b)});
  $('#chatAdd').onclick=()=>{const d=panel('<h2>新的相遇</h2><button class="menu-button" id="addCharacter">创建角色 <span>＋</span></button><button class="menu-button" id="addGroup">创建群聊 <span>＋</span></button><button class="secondary full" id="closeAdd">取消</button>');$('#addCharacter').onclick=()=>{d.close();editRole()};$('#addGroup').onclick=()=>{d.close();editGroup()};$('#closeAdd').onclick=()=>d.close()};
  $('#openMoments').onclick=()=>go('moments');$('#openGroups').onclick=()=>editGroup();$('#openMemories').onclick=()=>go('memory');if($('#chatApi'))$('#chatApi').onclick=()=>go('api');
}
function cardHTML(m){if(!m.card)return '';const c=m.card;return `<div class="gift-card ${c.type==='redpacket'?'packet':'transfer'}"><div class="gift-main"><span>${c.type==='redpacket'?'福':'↗'}</span><div><strong>${c.type==='redpacket'?'心意红包':'暖心转账'} · ¥${escapeHtml(c.amount)}</strong><small>${escapeHtml(c.note||'一点小小的心意')}</small></div></div><div class="gift-foot">虚拟互动 · ${c.status==='received'?'已领取':m.role==='user'?'已发送':'待领取'}</div>${m.role==='assistant'&&c.status==='pending'?`<button class="receive-card" data-receive="${m.id}">${c.type==='redpacket'?'拆开红包':'收下心意'}</button>`:''}</div>`}
function sendGift(r){if(busy){toast('等本轮回复完成后再发送');return}const d=panel(`<form id="giftForm"><h2>送一份小心意</h2><div class="notice">可用零钱 ¥ ${PalaisWallet.money(wallet.balance)}</div><label>卡片类型<select name="kind"><option value="redpacket">红包</option><option value="transfer">转账</option></select></label><label>金额<input name="amount" type="number" min="0.01" max="100000" step="0.01" required placeholder="例如：52.00"></label><label>留言<input name="note" maxlength="80" placeholder="愿你今天开心"></label><p class="api-note">这是虚拟零钱，发送成功即扣款，聊天回复失败不会重复扣款。</p><div class="actions"><button type="button" class="secondary" id="cancelGift">取消</button><button class="primary">发送卡片</button></div></form>`);$('#cancelGift').onclick=()=>d.close();$('#giftForm').onsubmit=e=>{e.preventDefault();const f=e.target,amount=Number(f.amount.value);if(!Number.isFinite(amount)||amount<=0||amount>100000)return;if(PalaisWallet.cents(f.amount.value)>wallet.balance){toast('零钱余额不足，请调整金额');return}const card={type:f.kind.value,amount:amount.toFixed(2),note:f.note.value.trim(),status:'sent'};if(!apiReady()){toast('请先连接聊天 API');return}d.close();sendMessage(r,card.note||'送给你的一点心意。',card)}}
